/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: slot, id, entry, tags, suggestion, project, context, ticks, code, stored, ready, trackDecision,
 *              row, tracklist, appendDoc, appendContext, tracklistOf, numberingOf
 *   Constants: importId, manifest, targetId, albumReuse
 * Tests
 *   - suggestions for empty or file-tag values arrive ticked, lookup and administrator values unticked, equal values resolved and changed values as conflicts
 *   - Artist entries resolve by name, role and join phrase in order, never by key or MusicBrainz ID
 *   - a label equal by name resolves itself and keeps its MusicBrainz ID, while empty or file-tag labels and Disc Numbers arrive ticked
 *   - an approval applies ticked suggestions, rejects unticked ones and accepts resolved ones, making accepted values the administrator's own
 *   - an approval refuses a missing, stale or conflicting tick and asks an editor without ticks to reload
 *   - the tick body is bounded before fingerprinting: exact fields, a generation and at most 304 distinct suggestion IDs
 *   - Publish waits for uploads, an active lookup and a queued or running analysis, and the budget shows what is left
 *   - Publish waits for a lookup cover staging only while it is queued or running within its grant, never after it settled or expired, and never as an upload
 *   - a new Album without a primary entry says at once when its files or the applied release credit only a placeholder, but an append or a primary entry does not
 *   - Publish does not wait for the upload of a file whose track is explicitly skipped or reused, but waits for any other file without a confirmed upload
 *   - Publish waits while any upload is still in flight, a skipped file's or a cover's included, until no transfer can land
 *   - a stored manifest in a shape this release does not know reads as its sanitized view instead of failing the summary
 *   - the identity rows left to answer are the Album, each track not skipped and, unless appending, each Artist entry and the label
 *   - an append tracklist is listed only for a saved Album reuse whose read target is that Album and holds a valid expected tracklist, and its key is absent otherwise
 *   - rows are filled by members at their position, a missing Disc Number counting as disc 1, and an invalid Track Number fills no row
 *   - each file lists its known duration and whether it is appended: the saved track decision wins, else the preselection, and an undecided file is appended
 *   - the numbering takes the rows every largest pairing gives a file: an extra bonus file and ambiguous durations are left unnumbered
 *   - numbers lookup wrote do not constrain the numbering and are replaced, file-tag numbers do, and a file with the administrator's own numbers is left out and takes its row
 *   - the numbering proposes the row title only for an empty or automatic title, and is not offered when it would grow the draft past its size cap
 *   - an Album reuse without a string candidate lists no append tracklist, and a file at the administrator's own position outside the tracklist or on a filled row takes no missing-file row
 *   - a complete publication lists no append tracklist, since the import's own new members then fill its rows, while an unfinished one still does
 *   - the numbering never places a file on a position an appended file it leaves unmoved keeps, and a file left out for that keeps its own position in turn
 * @end-catalog */

/**
 * The Review and publish summary's server state and Luna ticks without a database: tick defaults (empty or file-tag values
 * ticked, lookup or administrator values unticked, equal values resolved, changed values conflicts), the approval's atomic
 * application of the shown ticks and its refusals, the bounded tick body, what Publish waits for, the placeholder-only state
 * and the analysis budget. All names, identifiers and accounts are synthetic.
 */
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { ObjectId } from 'mongodb';
// The database module loads first; importing adminImportService before it trips the index import cycle.
import '../../src/infrastructure/database';
import { AdminImportError, type ImportManifest } from '../../src/administration/import/adminImportContract';
import { defaultDraftV2, type ImportArtistEntry, type ImportDecisionV2, type ImportDraftV2 } from '../../src/administration/import/adminImportDraft';
import type { ImportAsset } from '../../src/administration/import/adminImportMediaTypes';
import type { AdminImportDocument } from '../../src/administration/import/adminImportService';
import { applySuggestionTicks, boundSuggestionTicks, sameSuggestedValue } from '../../src/administration/import/adminImportLunaTicks';
import { importIdentityAnswers, importSummaryView, importUploadsWaiting } from '../../src/administration/import/adminImportSummary';
import type { MetadataLookupRecord } from '../../src/administration/lookup/metadataLookupRecord';

const importId = '0000000000000000000000d3';
const slot = (index: number) => `0000000a-0000-4000-a000-${String(index + 1).padStart(12, '0')}`;
const manifest: ImportManifest = { rootLabel: 'Synthetic Folder', files: [0, 1].map(index => ({ slotId: slot(index), filename: `${index}.flac`, relativePath: `Synthetic Folder/${index}.flac`, byteLength: 1 })) };
const id = (index: number) => String(index).padStart(24, 'c');
const entry = (name: string, key = '30000000-0000-4000-8000-000000000001', role: ImportArtistEntry['role'] = 'primary'): ImportArtistEntry => ({ key, name, role, joinPhrase: null, musicBrainzId: null });
const tags = (albumArtists: string[], artists: string[] = []) => ({ version: 2, title: null, album: null, artists, albumArtists, label: null, year: null, discNumber: null,
    trackNumber: null, durationMs: 200_000, identifiers: { barcode: null, catalogNumber: null, isrc: null, musicBrainzReleaseId: null }, flagged: [] });
const suggestion = (index: number, field: string, baseline: unknown, value: unknown, slotId: string | null = null) =>
    ({ id: id(index), generation: 1, scope: slotId ? 'track' : 'album', slotId, field, baseline, value, source: 'folder', evidence: 'Synthetic Folder', decision: 'pending' });
function project(draft: (value: ImportDraftV2) => void = () => {}, origins: Record<string, 'automatic' | 'administrator'> = {}): AdminImportDocument {
    const value = defaultDraftV2(manifest); draft(value);
    return { _id: new ObjectId(importId), purpose: 'import', draftVersion: 2, draft: value, draftOrigins: origins, manifest,
        analysis: { state: 'complete', generation: 1 }, attemptsUsed: 3, media: { assets: [] }, revision: 3, valueRevision: 0, decisions: [], suggestions: [], receipts: [],
        updatedAt: new Date(0) } as unknown as AdminImportDocument;
}
/** The summary context: read now, `daily` provider calls used today, lookup configured and no identity row left to answer. */
const context = (daily: number) => ({ now: new Date(), dailyAttemptsUsed: daily, lookupAvailable: true, identityAnswers: 0 });
const ticks = (doc: AdminImportDocument) => Object.fromEntries(importSummaryView(doc, null, context(0)).luna.map(item => [item.id, item.tick]));
const code = (expected: string) => (error: unknown) => error instanceof AdminImportError && error.code === expected;
const stored = (doc: AdminImportDocument) => doc.draft as ImportDraftV2;
const ready = (doc: AdminImportDocument, credits: ReturnType<typeof tags>[]) => {
    doc.media = { assets: manifest.files.map((file, index) => ({ slotId: file.slotId, operationId: id(80 + index), state: 'ready', sha256: 'a'.repeat(64), tags: credits[index] }) as unknown as ImportAsset) } as AdminImportDocument['media'];
};

test('suggestions for empty or file-tag values arrive ticked, lookup and administrator values unticked, equal values resolved and changed values as conflicts', () => {
    const doc = project(draft => {
        draft.album.title = 'Tag Title'; draft.album.releaseDate = { year: 2020, month: null, day: null };
        draft.tracks[0].title = 'Lookup Song'; draft.tracks[1].title = 'Mine'; draft.tracks[1].trackNumber = 2; draft.album.artists = [entry('Synthetic Lead')];
    }, { 'album:title': 'automatic', 'album:releaseDate': 'automatic', [`tracks:${slot(0)}:title`]: 'automatic', 'album:artists': 'automatic' });
    doc.suggestions = [
        suggestion(1, 'title', 'Tag Title', 'Luna Title'),
        // Written by file tags after analysis started: an automatic value is replaced whatever its baseline.
        suggestion(2, 'releaseDate', null, { year: 2021, month: null, day: null }),
        suggestion(3, 'title', 'Lookup Song', 'Luna Song', slot(0)),
        suggestion(4, 'title', 'Mine', 'Luna Mine', slot(1)),
        suggestion(5, 'trackNumber', 2, 2, slot(1)),
        suggestion(6, 'trackNumber', null, 1, slot(0)),
        // Artist entries are never replaced once they changed since analysis, automatic ones included.
        suggestion(7, 'artists', [], [entry('Luna Lead', '30000000-0000-4000-8000-000000000009')]),
        { ...suggestion(8, 'title', 'Old', 'Gone'), decision: 'rejected' }
    ] as AdminImportDocument['suggestions'];
    const lookup = { applied: { values: [{ path: `tracks.${slot(0)}.title`, value: 'Lookup Song', slotId: slot(0) }] } } as unknown as MetadataLookupRecord;
    const view = importSummaryView(doc, lookup, context(0));
    assert.deepEqual(Object.fromEntries(view.luna.map(item => [item.id, item.tick])), {
        [id(1)]: 'ticked', [id(2)]: 'ticked', [id(3)]: 'unticked', [id(4)]: 'unticked', [id(5)]: 'resolved', [id(6)]: 'ticked', [id(7)]: 'conflict'
    });
    // Without the applied lookup value, the same automatic track title rests on file tags and arrives ticked.
    assert.equal(ticks(doc)[id(3)], 'ticked');
    // An administrator value changed since analysis cannot be ticked.
    stored(doc).tracks[1].title = 'Edited'; assert.equal(ticks(doc)[id(4)], 'conflict');
});

test('Artist entries resolve by name, role and join phrase in order, never by key or MusicBrainz ID', () => {
    const current = [entry('Lead', '30000000-0000-4000-8000-000000000001'), { ...entry('Guest', '30000000-0000-4000-8000-000000000002', 'featured'), joinPhrase: null }];
    const suggested = [{ ...entry('Lead', '30000000-0000-4000-8000-00000000000a'), musicBrainzId: '0000000b-0000-4000-8000-000000000001' }, entry('Guest', '30000000-0000-4000-8000-00000000000b', 'featured')];
    assert.equal(sameSuggestedValue('album.artists', current, suggested), true);
    assert.equal(sameSuggestedValue('album.artists', current, [suggested[1], suggested[0]]), false);
    assert.equal(sameSuggestedValue('album.artists', current, [suggested[0], { ...suggested[1], role: 'primary' }]), false);
    assert.equal(sameSuggestedValue('album.artists', current, [{ ...suggested[0], name: 'lead' }, suggested[1]]), false);
    assert.equal(sameSuggestedValue('album.title', 'A', 'A'), true);
});

test('a label equal by name resolves itself and keeps its MusicBrainz ID, while empty or file-tag labels and Disc Numbers arrive ticked', () => {
    const mbid = '0000000b-0000-4000-8000-000000000002', label = (name: string, musicBrainzId: string | null = null) => ({ name, musicBrainzId });
    assert.equal(sameSuggestedValue('album.label', label('Amet Records', mbid), label('Amet Records')), true);
    assert.equal(sameSuggestedValue('album.label', label('Amet Records'), label('amet records')), false);
    assert.equal(sameSuggestedValue('album.label', null, label('Amet Records')), false);
    const doc = project(draft => { draft.album.label = label('Amet Records', mbid); draft.tracks[1].discNumber = 1; }, { [`tracks:${slot(1)}:discNumber`]: 'automatic' });
    doc.suggestions = [suggestion(1, 'label', label('Amet Records', mbid), label('Amet Records')), suggestion(2, 'discNumber', null, 2, slot(0)), suggestion(3, 'discNumber', null, 2, slot(1))] as AdminImportDocument['suggestions'];
    ready(doc, [tags([]), { ...tags([]), discNumber: 1 }]);
    assert.deepEqual(ticks(doc), { [id(1)]: 'resolved', [id(2)]: 'ticked', [id(3)]: 'ticked' });
    applySuggestionTicks(doc, stored(doc), { generation: 1, ticked: [id(2), id(3)], unticked: [] });
    assert.deepEqual([stored(doc).album.label, stored(doc).tracks.map(track => track.discNumber)], [label('Amet Records', mbid), [2, 2]]);
    assert.deepEqual(doc.suggestions.map(item => item.decision), ['accepted', 'accepted', 'accepted']);
    // An empty label, or one resting only on file tags, arrives ticked; the administrator's own arrives unticked.
    const empty = project(); empty.suggestions = [suggestion(1, 'label', null, label('Amet Records'))] as AdminImportDocument['suggestions'];
    assert.equal(ticks(empty)[id(1)], 'ticked');
    const automatic = project(draft => { draft.album.label = label('Tag Records'); }, { 'album:label': 'automatic' });
    automatic.suggestions = [suggestion(1, 'label', label('Tag Records'), label('Amet Records'))] as AdminImportDocument['suggestions'];
    assert.equal(ticks(automatic)[id(1)], 'ticked');
    applySuggestionTicks(automatic, stored(automatic), { generation: 1, ticked: [id(1)], unticked: [] });
    assert.deepEqual([stored(automatic).album.label, automatic.draftOrigins?.['album:label']], [label('Amet Records'), 'administrator']);
    const mine = project(draft => { draft.album.label = label('Mine Records'); }); mine.suggestions = [suggestion(1, 'label', label('Mine Records'), label('Amet Records'))] as AdminImportDocument['suggestions'];
    assert.equal(ticks(mine)[id(1)], 'unticked');
});

test('an approval applies ticked suggestions, rejects unticked ones and accepts resolved ones, making accepted values the administrator\'s own', () => {
    const doc = project(draft => { draft.tracks[1].trackNumber = 2; }, {});
    doc.suggestions = [suggestion(1, 'title', '', 'Luna Title'), suggestion(2, 'title', '', 'Luna Song', slot(0)), suggestion(3, 'trackNumber', 2, 2, slot(1))] as AdminImportDocument['suggestions'];
    doc.decisions = [{ scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'create-distinct', candidateId: null, candidateRevision: null }] as AdminImportDocument['decisions'];
    applySuggestionTicks(doc, stored(doc), { generation: 1, ticked: [id(1)], unticked: [id(2)] });
    assert.deepEqual([stored(doc).album.title, stored(doc).tracks[0].title], ['Luna Title', '']);
    assert.deepEqual(doc.suggestions.map(item => item.decision), ['accepted', 'rejected', 'accepted']);
    assert.equal(doc.draftOrigins?.['album:title'], 'administrator');
    assert.equal(doc.decisions.length, 1, 'decisions still bound to their rows are kept');
});

test('an approval refuses a missing, stale or conflicting tick and asks an editor without ticks to reload', () => {
    const fresh = () => {
        const doc = project(draft => { draft.tracks[0].title = 'Mine'; }, {});
        doc.suggestions = [suggestion(1, 'title', '', 'Luna Title'), suggestion(2, 'title', 'Before', 'Luna Song', slot(0))] as AdminImportDocument['suggestions'];
        return doc;
    };
    assert.throws(() => applySuggestionTicks(fresh(), stored(fresh()), { generation: 1, ticked: [id(1)], unticked: [] }), code('ADMIN_IMPORT_REVIEW_REQUIRED'));
    assert.throws(() => applySuggestionTicks(fresh(), stored(fresh()), { generation: 1, ticked: [id(1), id(9)], unticked: [id(2)] }), code('ADMIN_IMPORT_SUGGESTION_STALE'));
    assert.throws(() => applySuggestionTicks(fresh(), stored(fresh()), { generation: 2, ticked: [id(1)], unticked: [id(2)] }), code('ADMIN_IMPORT_SUGGESTION_STALE'));
    let doc = fresh(); assert.throws(() => applySuggestionTicks(doc, stored(doc), { generation: 1, ticked: [id(1), id(2)], unticked: [] }), code('ADMIN_IMPORT_FIELD_CONFLICT'));
    doc = fresh(); assert.throws(() => applySuggestionTicks(doc, stored(doc), undefined), code('ADMIN_IMPORT_RELOAD_REQUIRED'));
    // With nothing left to answer, an editor without ticks is admitted and resolved suggestions are accepted.
    doc = project(draft => { draft.album.title = 'Luna Title'; }); doc.suggestions = [suggestion(1, 'title', '', 'Luna Title')] as AdminImportDocument['suggestions'];
    applySuggestionTicks(doc, stored(doc), undefined); assert.equal(doc.suggestions[0].decision, 'accepted');
    doc = project(); applySuggestionTicks(doc, stored(doc), undefined); assert.deepEqual(doc.suggestions, []);
    // A confirmation that showed no suggestion binds no generation; one that showed some does.
    applySuggestionTicks(doc, stored(doc), { generation: 7, ticked: [], unticked: [] });
    doc = fresh(); assert.throws(() => applySuggestionTicks(doc, stored(doc), { generation: 7, ticked: [], unticked: [] }), code('ADMIN_IMPORT_REVIEW_REQUIRED'));
});

test('the tick body is bounded before fingerprinting: exact fields, a generation and at most 304 distinct suggestion IDs', () => {
    const invalid = (value: unknown) => assert.throws(() => boundSuggestionTicks(value), code('ADMIN_IMPORT_INVALID_INPUT'));
    boundSuggestionTicks({ generation: 1, ticked: [id(1)], unticked: [id(2)] });
    boundSuggestionTicks({ generation: 0, ticked: Array.from({ length: 4 }, (_, index) => String(index).padStart(24, 'a')), unticked: Array.from({ length: 300 }, (_, index) => String(index).padStart(24, '0')) });
    invalid(null); invalid([]); invalid({ generation: 1, ticked: [] }); invalid({ generation: 1, ticked: [], unticked: [], extra: true });
    invalid({ generation: -1, ticked: [], unticked: [] }); invalid({ generation: 1.5, ticked: [], unticked: [] }); invalid({ generation: 1, ticked: 'x', unticked: [] });
    invalid({ generation: 1, ticked: [id(1)], unticked: [id(1)] }); invalid({ generation: 1, ticked: ['not-an-id'], unticked: [] });
    invalid({ generation: 1, ticked: [], unticked: Array.from({ length: 305 }, (_, index) => String(index).padStart(24, '0')) });
});

test('Publish waits for uploads, an active lookup and a queued or running analysis, and the budget shows what is left', () => {
    const doc = project();
    assert.deepEqual(importSummaryView(doc, null, context(5)).waiting, { uploads: true, lookup: false, cover: false, analysis: false });
    ready(doc, [tags(['Synthetic Lead']), tags(['Synthetic Lead'])]);
    assert.deepEqual(importSummaryView(doc, null, context(5)).waiting, { uploads: false, lookup: false, cover: false, analysis: false });
    for (const state of ['queued', 'running', 'retrying'] as const) assert.equal(importSummaryView(doc, { state } as MetadataLookupRecord, context(5)).waiting.lookup, true);
    for (const state of ['complete', 'unavailable', 'stopped', 'superseded'] as const) assert.equal(importSummaryView(doc, { state } as MetadataLookupRecord, context(5)).waiting.lookup, false);
    doc.lookupGate = { fence: 2, run: 1, state: 'queued', blocking: true }; assert.equal(importSummaryView(doc, null, context(5)).waiting.lookup, true);
    doc.analysis.state = 'running'; assert.equal(importSummaryView(doc, null, context(5)).waiting.analysis, true);
    assert.deepEqual(importSummaryView(doc, null, context(5)).analysis, { runs: 1, attempts: 19, daily: 215 });
    doc.analysis.generation = 2; doc.attemptsUsed = 30; assert.deepEqual(importSummaryView(doc, null, context(400)).analysis, { runs: 0, attempts: 0, daily: 0 });
});

test('Publish waits for a lookup cover staging only while it is queued or running within its grant, never after it settled or expired, and never as an upload', () => {
    const doc = project(), now = new Date('2026-10-19T12:00:00Z');
    ready(doc, [tags(['Synthetic Lead']), tags(['Synthetic Lead'])]);
    const waiting = (state: string, grantExpiresAt: unknown = new Date(now.getTime() + 60_000)) => {
        doc.media!.lookupCover = { candidateKey: 'musicbrainz:0000000b-0000-4000-8000-000000000001', releaseId: '0000000b-0000-4000-8000-000000000001',
            operationId: '0000000b-0000-4000-8000-000000000099', state, issue: null, actorId: id(1), grantExpiresAt, due: true, leaseOwner: null, leaseUntil: null, updatedAt: now } as never;
        return importSummaryView(doc, null, { ...context(0), now }).waiting;
    };
    assert.equal(importSummaryView(doc, null, { ...context(0), now }).waiting.cover, false, 'no job');
    assert.deepEqual(waiting('queued'), { uploads: false, lookup: false, cover: true, analysis: false });
    assert.equal(waiting('running').cover, true);
    for (const state of ['staged', 'failed', 'skipped', 'idle']) assert.equal(waiting(state).cover, false, state);
    assert.equal(waiting('queued', now).cover, false, 'a grant ending now no longer holds Publish');
    assert.equal(waiting('running', new Date(now.getTime() - 1)).cover, false, 'expired');
    assert.equal(waiting('queued', 'tomorrow').cover, false, 'a malformed grant never holds Publish');
    // A failed staging whose admitted record has not settled is never an upload Publish waits for; a running one waits as the cover.
    const lookupSlot = 'lookup-musicbrainz:0000000b-0000-4000-8000-000000000001';
    doc.media!.assets.push({ ...doc.media!.assets[0], slotId: lookupSlot, contentType: 'image/jpeg', state: 'pending', updatedAt: now, leaseUntil: null, transferDeadline: null } as ImportAsset);
    assert.deepEqual(waiting('failed'), { uploads: false, lookup: false, cover: false, analysis: false });
    assert.equal(importUploadsWaiting(doc, [], now), false);
    assert.deepEqual(waiting('running'), { uploads: false, lookup: false, cover: true, analysis: false });
});

test('a new Album without a primary entry says at once when its files or the applied release credit only a placeholder, but an append or a primary entry does not', () => {
    const doc = project();
    ready(doc, [tags(['Various Artists']), tags([], ['various artists'])]);
    assert.equal(importSummaryView(doc, null, context(0)).placeholderOnly, true);
    ready(doc, [tags(['Various Artists']), tags(['Synthetic Lead'])]); assert.equal(importSummaryView(doc, null, context(0)).placeholderOnly, false);
    const flagged = { applied: { values: [], flagged: [{ path: 'album.artists', reason: 'placeholder' }] } } as unknown as MetadataLookupRecord;
    assert.equal(importSummaryView(doc, flagged, context(0)).placeholderOnly, true);
    stored(doc).album.artists = [entry('Synthetic Lead', undefined, 'featured')]; assert.equal(importSummaryView(doc, flagged, context(0)).placeholderOnly, true);
    stored(doc).album.artists = [entry('Synthetic Lead')]; assert.equal(importSummaryView(doc, flagged, context(0)).placeholderOnly, false);
    stored(doc).album.artists = [];
    doc.decisions = [{ scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'reuse', candidateId: id(70), candidateRevision: 'f'.repeat(64) }] as AdminImportDocument['decisions'];
    const view = importSummaryView(doc, flagged, context(0));
    assert.deepEqual([view.append, view.placeholderOnly], [true, false]);
    // Files without version-2 evidence credit nothing.
    const legacy = project(); ready(legacy, [{ ...tags(['Various Artists']), version: 1 }, tags(['Various Artists'])]); assert.equal(importSummaryView(legacy, null, context(0)).placeholderOnly, false);
});

test('Publish does not wait for the upload of a file whose track is explicitly skipped or reused, but waits for any other file without a confirmed upload', () => {
    const doc = project(), skip = (index: number) => ({ scope: 'track', slotId: slot(index), entryKey: null, boundName: null, action: 'skip', candidateId: null, candidateRevision: null });
    ready(doc, [tags(['Synthetic Lead']), tags(['Synthetic Lead'])]);
    doc.media!.assets = doc.media!.assets.slice(0, 1);
    assert.equal(importSummaryView(doc, null, context(0)).waiting.uploads, true);
    doc.decisions = [skip(1)] as AdminImportDocument['decisions']; assert.equal(importSummaryView(doc, null, context(0)).waiting.uploads, false);
    // Skipping the confirmed file instead leaves the other one waited for, as does any other decision for it.
    doc.decisions = [skip(0)] as AdminImportDocument['decisions']; assert.equal(importSummaryView(doc, null, context(0)).waiting.uploads, true);
    doc.decisions = [{ ...skip(1), action: 'create-distinct' }] as AdminImportDocument['decisions']; assert.equal(importSummaryView(doc, null, context(0)).waiting.uploads, true);
    // An upload that is not confirmed yet is still waited for.
    doc.decisions = []; doc.media!.assets = [doc.media!.assets[0], { ...doc.media!.assets[0], slotId: slot(1), state: 'pending', updatedAt: new Date() } as ImportAsset];
    assert.equal(importSummaryView(doc, null, context(0)).waiting.uploads, true);
    // In an append, a track reusing an existing member keeps that member's media, so its file needs no upload.
    const album = { scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'reuse', candidateId: id(70), candidateRevision: 'f'.repeat(64) };
    doc.media!.assets = doc.media!.assets.slice(0, 1);
    doc.decisions = [album, { ...skip(1), action: 'reuse', candidateId: id(71), candidateRevision: 'f'.repeat(64) }] as AdminImportDocument['decisions'];
    assert.deepEqual([importSummaryView(doc, null, context(0)).append, importSummaryView(doc, null, context(0)).waiting.uploads], [true, false]);
});

test('Publish waits while any upload is still in flight, a skipped file\'s or a cover\'s included, until no transfer can land', () => {
    const doc = project(), now = new Date('2026-10-01T00:00:00.000Z'), skip = { scope: 'track', slotId: slot(1), entryKey: null, boundName: null, action: 'skip', candidateId: null, candidateRevision: null };
    ready(doc, [tags(['Synthetic Lead']), tags(['Synthetic Lead'])]);
    doc.decisions = [skip] as AdminImportDocument['decisions'];
    const pending = (slotId: string, extra: Partial<ImportAsset>) => ({ ...doc.media!.assets[0], slotId, state: 'pending', updatedAt: now, leaseUntil: null, transferDeadline: null, ...extra }) as ImportAsset;
    // A skipped file's upload under a live lease can still land.
    doc.media!.assets = [doc.media!.assets[0], pending(slot(1), { leaseUntil: new Date(now.getTime() + 60_000) })];
    assert.equal(importUploadsWaiting(doc, doc.decisions, now), true);
    // Once its lease ended and its transfer deadline passed, the pending record proves nothing is in flight.
    doc.media!.assets[1] = pending(slot(1), { leaseUntil: new Date(now.getTime() - 1), transferDeadline: new Date(now.getTime() - 1) });
    assert.equal(importUploadsWaiting(doc, doc.decisions, now), false);
    // A manual cover still uploading holds Publish as well, until its settle window ends.
    doc.media!.assets[1] = pending('cover', {});
    assert.equal(importSummaryView(doc, null, { ...context(0), now }).waiting.uploads, true);
    assert.equal(importUploadsWaiting(doc, doc.decisions, new Date(now.getTime() + 180_000)), false);
});

test('a stored manifest in a shape this release does not know reads as its sanitized view instead of failing the summary', () => {
    for (const manifest of [null, { rootLabel: 'x' }, { rootLabel: 'x', files: 'not a list' }, { files: [null, 7, { slotId: 'not-a-uuid' }] }]) {
        const doc = { ...project(), manifest } as unknown as AdminImportDocument;
        const view = importSummaryView(doc, null, context(0));
        assert.deepEqual([view.waiting.uploads, view.placeholderOnly, view.luna], [false, false, []]);
    }
});

test('the identity rows left to answer are the Album, each track not skipped and, unless appending, each Artist entry and the label', () => {
    const draft = defaultDraftV2(manifest); draft.album.artists = [entry('Synthetic Lead')]; draft.album.label = { name: 'Synthetic Records', musicBrainzId: null };
    const decision = (scope: string, action: string, extra: Record<string, unknown> = {}) => ({ scope, slotId: null, entryKey: null, boundName: null, action, candidateId: null, candidateRevision: null, ...extra }) as never;
    assert.equal(importIdentityAnswers(draft, [], []), 5);
    const answered = [decision('album', 'create-distinct'), decision('track', 'create-distinct', { slotId: slot(0) }), decision('track', 'skip', { slotId: slot(1) })];
    // The entry's decision binds its key and the name it was made for; the label's binds the label name.
    assert.equal(importIdentityAnswers(draft, answered, [decision('artist', 'create-distinct', { entryKey: entry('x').key, boundName: 'Synthetic Lead', preselected: true })]), 1);
    assert.equal(importIdentityAnswers(draft, [...answered, decision('artist', 'create-distinct', { entryKey: entry('x').key, boundName: 'Renamed' }), decision('label', 'create-distinct', { boundName: 'Synthetic Records' })], []), 1);
    // An append applies no entry or label, so neither needs an answer; its tracks still do.
    assert.equal(importIdentityAnswers(draft, [decision('album', 'reuse', { candidateId: id(70) })], []), 2);
    const view = importSummaryView(project(), null, { ...context(0), lookupAvailable: false, identityAnswers: 3 });
    assert.deepEqual([view.lookupAvailable, view.identityAnswers], [false, 3]);
    // Reusing a record and replacing its MusicBrainz ID answers a row, and so does an exact-ID reuse the review preselected.
    const withId = defaultDraftV2(manifest); withId.album.artists = [{ ...entry('Synthetic Lead'), musicBrainzId: '00000000-0000-4000-8000-000000000001' }];
    withId.album.label = { name: 'Synthetic Records', musicBrainzId: '00000000-0000-4000-8000-000000000009' };
    const replaced = decision('artist', 'replace', { entryKey: entry('x').key, boundName: 'Synthetic Lead', boundMusicBrainzId: '00000000-0000-4000-8000-000000000001', candidateId: id(71) });
    const exact = decision('label', 'reuse', { boundName: 'Synthetic Records', boundMusicBrainzId: '00000000-0000-4000-8000-000000000009', candidateId: id(72), preselected: true });
    assert.equal(importIdentityAnswers(withId, [...answered, replaced], [exact]), 0);
    // A decision bound to another (or no) ID answers nothing for an entry that carries one.
    assert.equal(importIdentityAnswers(withId, [...answered, { ...replaced, boundMusicBrainzId: null } as never], [exact]), 1);
});

const targetId = id(70);
const albumReuse = { scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'reuse', candidateId: targetId, candidateRevision: 'f'.repeat(64) };
const trackDecision = (index: number, action: string, preselected = false) => ({ scope: 'track', slotId: slot(index), entryKey: null, boundName: null, action,
    candidateId: action === 'reuse' ? id(71 + index) : null, candidateRevision: action === 'reuse' ? 'f'.repeat(64) : null, ...preselected ? { preselected: true } : {} }) as ImportDecisionV2;
const row = (discNumber: number, trackNumber: number, durationMs: number | null = null, title = `Row ${discNumber}-${trackNumber}`) => ({ discNumber, trackNumber, title, durationMs });
const tracklist = (rows: ReturnType<typeof row>[]) => ({ source: 'musicbrainz', appliedAt: new Date('2026-10-01T00:00:00.000Z'), rows });
/**
 * A saved append of one file per entry of `durations` to the target Album: a number is version-2 tag milliseconds, a string a
 * legacy `m:ss` duration and null no known duration. Every file is uploaded; numbers and titles are unknown unless `draft` sets them.
 */
function appendDoc(durations: (number | string | null)[], draft: (value: ImportDraftV2) => void = () => {}, origins: Record<string, 'automatic' | 'administrator'> = {}): AdminImportDocument {
    const files = durations.map((_duration, index) => ({ slotId: slot(index), filename: `${index}.flac`, relativePath: `Synthetic Folder/${index}.flac`, byteLength: 1 }));
    const value = defaultDraftV2({ rootLabel: 'Synthetic Folder', files }); draft(value);
    const assets = durations.map((duration, index) => ({ slotId: slot(index), operationId: id(80 + index), state: 'ready', sha256: 'a'.repeat(64),
        tags: typeof duration === 'number' ? { ...tags([]), durationMs: duration } : null, ...typeof duration === 'string' ? { duration } : {} }) as unknown as ImportAsset);
    return { ...project(), manifest: { rootLabel: 'Synthetic Folder', files }, draft: value, draftOrigins: origins, decisions: [albumReuse], media: { assets } } as unknown as AdminImportDocument;
}
/** The summary context of an append whose target holds `rows` and members at the given numbers, with the identity preselections. */
const appendContext = (rows: ReturnType<typeof row>[] | unknown, members: { discNumber: unknown; trackNumber: unknown }[] = [], preselections: ImportDecisionV2[] = []) =>
    ({ ...context(0), appendTarget: { albumId: targetId, tracklist: Array.isArray(rows) ? tracklist(rows) : rows, members }, preselections });
const tracklistOf = (doc: AdminImportDocument, rows: Parameters<typeof appendContext>[0], members: Parameters<typeof appendContext>[1] = [], lookup: MetadataLookupRecord | null = null) =>
    importSummaryView(doc, lookup, appendContext(rows, members)).appendTracklist;
const numberingOf = (...args: Parameters<typeof tracklistOf>) => tracklistOf(...args)?.numbering;

test('an append tracklist is listed only for a saved Album reuse whose read target is that Album and holds a valid expected tracklist, and its key is absent otherwise', () => {
    const rows = [row(1, 1), row(1, 2)], doc = appendDoc([null]);
    assert.deepEqual(tracklistOf(doc, rows), { albumId: targetId, durationToleranceMs: 3000,
        rows: [{ ...row(1, 1), filled: false }, { ...row(1, 2), filled: false }], files: [{ slotId: slot(0), durationMs: null, durationPrecisionMs: 0, appended: true }],
        numbering: [] });
    // No saved Album reuse (a new Album, or an unsaved one), or no target read: none, and the summary has no such key, so it keeps
    // the shape it had before expected tracklists.
    assert.equal('appendTracklist' in importSummaryView({ ...doc, decisions: [] } as AdminImportDocument, null, appendContext(rows)), false);
    assert.equal(tracklistOf({ ...doc, decisions: [{ ...albumReuse, action: 'create-distinct', candidateId: null }] } as AdminImportDocument, rows), undefined);
    assert.equal('appendTracklist' in importSummaryView(doc, null, context(0)), false);
    assert.equal(importSummaryView(doc, null, { ...appendContext(rows), appendTarget: null }).appendTracklist, undefined);
    // A target other than the saved reuse, or a malformed stored tracklist, lists nothing.
    assert.equal(importSummaryView(doc, null, { ...appendContext(rows), appendTarget: { albumId: id(79), tracklist: tracklist(rows), members: [] } }).appendTracklist, undefined);
    for (const malformed of [null, 'rows', { ...tracklist(rows), source: 'discogs' }, { ...tracklist(rows), appliedAt: 'yesterday' }, tracklist([]), tracklist([row(1, 1), row(1, 1)])])
        assert.equal(tracklistOf(doc, malformed), undefined);
});

test('rows are filled by members at their position, a missing Disc Number counting as disc 1, and an invalid Track Number fills no row', () => {
    const rows = [row(1, 1), row(1, 2), row(2, 1), row(2, 2)];
    // The members' lifecycle state and visibility are never read: any member at a row's position fills it.
    const members = [{ discNumber: undefined, trackNumber: 1 }, { discNumber: 2, trackNumber: 0 }, { discNumber: 2, trackNumber: 2.5 }, { discNumber: 2, trackNumber: 2 }, { discNumber: null, trackNumber: 9 }];
    assert.deepEqual(tracklistOf(appendDoc([null]), rows, members)!.rows.map(item => item.filled), [true, false, false, true]);
    // Two members at one position fill one row.
    assert.deepEqual(tracklistOf(appendDoc([null]), rows, [{ discNumber: 1, trackNumber: 2 }, { discNumber: 1, trackNumber: 2 }])!.rows.map(item => item.filled), [false, true, false, false]);
});

test('each file lists its known duration and whether it is appended: the saved track decision wins, else the preselection, and an undecided file is appended', () => {
    const doc = appendDoc([200_000, '3:20', null, 180_000, 180_000]);
    doc.media!.assets.push({ ...doc.media!.assets[2], state: 'pending', updatedAt: new Date(), tags: { ...tags([]), durationMs: 1000 } } as ImportAsset);
    doc.decisions = [albumReuse, trackDecision(0, 'create-distinct'), trackDecision(1, 'skip'), trackDecision(4, 'reuse')] as AdminImportDocument['decisions'];
    const preselections = [trackDecision(0, 'reuse', true), trackDecision(2, 'reuse', true), trackDecision(3, 'create-distinct', true)];
    const view = importSummaryView(doc, null, appendContext([row(1, 1)], [], preselections)).appendTracklist!;
    // Version-2 tag milliseconds are exact; a legacy m:ss duration has 1-second precision; a pending upload's evidence is not read.
    assert.deepEqual(view.files, [
        { slotId: slot(0), durationMs: 200_000, durationPrecisionMs: 0, appended: true },
        { slotId: slot(1), durationMs: 200_000, durationPrecisionMs: 1000, appended: false },
        { slotId: slot(2), durationMs: null, durationPrecisionMs: 0, appended: false },
        { slotId: slot(3), durationMs: 180_000, durationPrecisionMs: 0, appended: true },
        { slotId: slot(4), durationMs: 180_000, durationPrecisionMs: 0, appended: false }]);
    // Without a decision or a preselection a file still needs an answer, and is counted as appended meanwhile.
    assert.deepEqual(tracklistOf(doc, [row(1, 1)])!.files.map(file => file.appended), [true, false, true, true, false]);
});

test('the numbering takes the rows every largest pairing gives a file: an extra bonus file and ambiguous durations are left unnumbered', () => {
    const rows = [row(1, 1, 200_000), row(1, 2, 240_000, 'Second Row'), row(1, 3, 300_000, 'Third Row')], filled = [{ discNumber: 1, trackNumber: 1 }];
    // The bonus file fits no row by duration, so the other two files each have one row only; a file whose title is the
    // administrator's own keeps it.
    const doc = appendDoc([300_000, 420_000, 241_500], draft => { draft.tracks[2].title = 'Mine'; });
    assert.deepEqual(numberingOf(doc, rows, filled), [{ slotId: slot(0), discNumber: 1, trackNumber: 3, title: 'Third Row' }, { slotId: slot(2), discNumber: 1, trackNumber: 2, title: null }]);
    // A filled row is no slot: the file whose duration fits only it stays unnumbered.
    assert.deepEqual(numberingOf(appendDoc([200_000]), rows, filled), []);
    // Two files that fit both missing rows could take either: no file is numbered.
    assert.deepEqual(numberingOf(appendDoc([270_000, 270_000]), [row(1, 1, 269_000), row(1, 2, 271_000)]), []);
    assert.deepEqual(numberingOf(appendDoc([null, null]), [row(1, 1), row(1, 2)]), []);
    // A legacy whole-second duration gets one more second of tolerance.
    assert.deepEqual(numberingOf(appendDoc(['4:04']), [row(1, 1, 240_000), row(1, 2, 300_000)])!.map(entry => entry.trackNumber), [1]);
    assert.deepEqual(numberingOf(appendDoc(['4:05']), [row(1, 1, 240_000), row(1, 2, 300_000)])!.map(entry => entry.trackNumber), []);
    assert.deepEqual(numberingOf(appendDoc([243_000]), [row(1, 1, 240_000), row(1, 2, 300_000)])!.map(entry => entry.trackNumber), [1]);
    assert.deepEqual(numberingOf(appendDoc([243_001]), [row(1, 1, 240_000), row(1, 2, 300_000)])!.map(entry => entry.trackNumber), []);
    // Skipped and reused files are not appended, so they are never numbered.
    const skipped = appendDoc([300_000]); skipped.decisions = [albumReuse, trackDecision(0, 'skip')] as AdminImportDocument['decisions'];
    assert.deepEqual(numberingOf(skipped, rows, filled), []);
});

test('numbers lookup wrote do not constrain the numbering and are replaced, file-tag numbers do, and a file with the administrator\'s own numbers is left out and takes its row', () => {
    const rows = [row(1, 2), row(1, 3)], automatic = { [`tracks:${slot(0)}:trackNumber`]: 'automatic' } as const;
    // A file-tag Track Number 3 places the first file; the second then has (1, 2) only.
    const tagged = appendDoc([null, null], draft => { draft.tracks[0].trackNumber = 3; }, automatic);
    assert.deepEqual(numberingOf(tagged, rows), [{ slotId: slot(0), discNumber: 1, trackNumber: 3, title: 'Row 1-3' }, { slotId: slot(1), discNumber: 1, trackNumber: 2, title: 'Row 1-2' }]);
    // The same number written by the applied lookup candidate does not constrain, so either file could take either row.
    const lookup = { applied: { values: [{ path: `tracks.${slot(0)}.trackNumber`, value: 3, slotId: slot(0) }] } } as unknown as MetadataLookupRecord;
    assert.deepEqual(numberingOf(tagged, rows, [], lookup), []);
    // A lookup Track Number on a file whose duration fits another row is replaced by that row's.
    const replaced = appendDoc([240_000], draft => { draft.tracks[0].trackNumber = 3; }, automatic);
    assert.deepEqual(numberingOf(replaced, [row(1, 2, 240_000), row(1, 3, 300_000)], [], lookup), [{ slotId: slot(0), discNumber: 1, trackNumber: 2, title: 'Row 1-2' }]);
    assert.deepEqual(numberingOf(replaced, [row(1, 2, 240_000), row(1, 3, 300_000)]), []);
    // The administrator's own Disc and Track Number (no stored origin is the administrator's) leave the file out and take (1, 2).
    const own = appendDoc([null, null], draft => { draft.tracks[0].discNumber = 1; draft.tracks[0].trackNumber = 2; });
    assert.deepEqual(numberingOf(own, rows), [{ slotId: slot(1), discNumber: 1, trackNumber: 3, title: 'Row 1-3' }]);
    // An own Track Number without a Disc Number still pairs, and is numbered with the row's disc.
    const discless = appendDoc([null], draft => { draft.tracks[0].trackNumber = 3; });
    assert.deepEqual(numberingOf(discless, rows), [{ slotId: slot(0), discNumber: 1, trackNumber: 3, title: 'Row 1-3' }]);
    // A file-tag Disc Number on another disc fits no row.
    assert.deepEqual(numberingOf(appendDoc([null], draft => { draft.tracks[0].discNumber = 2; }, { [`tracks:${slot(0)}:discNumber`]: 'automatic' }), [row(1, 2)]), []);
});

test('the numbering proposes the row title only for an empty or automatic title, and is not offered when it would grow the draft past its size cap', () => {
    const rows = [row(1, 1, 100_000), row(1, 2, 200_000), row(1, 3, 300_000)];
    const doc = appendDoc([100_000, 200_000, 300_000], draft => { draft.tracks[0].title = 'Tag Title'; draft.tracks[1].title = 'Mine'; }, { [`tracks:${slot(0)}:title`]: 'automatic' });
    assert.deepEqual(numberingOf(doc, rows)!.map(entry => entry.title), ['Row 1-1', null, 'Row 1-3']);
    // Long titles of other files bring the draft close to 48 KB; numbering the last file with a long row title would pass it.
    const wide = '\u97f3'.repeat(300), count = 48;
    const durations = Array.from({ length: count + 1 }, (_value, index) => index === count ? 100_000 : null);
    const padded = appendDoc(durations, draft => draft.tracks.slice(0, count).forEach((track, index) => Object.assign(track, { title: wide, discNumber: 9, trackNumber: index + 1 })));
    const bytes = Buffer.byteLength(JSON.stringify(padded.draft));
    assert.ok(bytes < 48_000 && bytes + 900 > 48_000, String(bytes));
    assert.deepEqual(numberingOf(padded, [row(1, 1, 100_000, wide)]), []);
    assert.deepEqual(numberingOf(padded, [row(1, 1, 100_000, 'Short')]), [{ slotId: slot(count), discNumber: 1, trackNumber: 1, title: 'Short' }]);
});

test('an Album reuse without a string candidate lists no append tracklist, and a file at the administrator\'s own position outside the tracklist or on a filled row takes no missing-file row', () => {
    assert.equal(tracklistOf({ ...appendDoc([null]), decisions: [{ ...albumReuse, candidateId: 70 }] } as unknown as AdminImportDocument, [row(1, 1)]), undefined);
    const rows = [row(1, 1), row(1, 2)], filled = [{ discNumber: 1, trackNumber: 1 }];
    // The first file keeps its own numbers and is never numbered; the second still has the one missing-file row.
    for (const trackNumber of [9, 1]) {
        const doc = appendDoc([null, null], draft => { draft.tracks[0].discNumber = 1; draft.tracks[0].trackNumber = trackNumber; });
        assert.deepEqual(numberingOf(doc, rows, filled), [{ slotId: slot(1), discNumber: 1, trackNumber: 2, title: 'Row 1-2' }]);
    }
});

test('a complete publication lists no append tracklist, since the import\'s own new members then fill its rows, while an unfinished one still does', () => {
    const rows = [row(1, 1), row(1, 2)];
    for (const state of ['preparing', 'needsAttention', 'cancelled']) {
        const doc = appendDoc([null]); doc.media!.publication = { state } as never;
        assert.deepEqual(tracklistOf(doc, rows)!.rows.map(item => item.filled), [false, false], state);
    }
    const complete = appendDoc([null], draft => { draft.tracks[0].discNumber = 1; draft.tracks[0].trackNumber = 2; }); complete.media!.publication = { state: 'complete' } as never;
    assert.equal('appendTracklist' in importSummaryView(complete, null, appendContext(rows, [{ discNumber: 1, trackNumber: 2 }])), false);
});

test('the numbering never places a file on a position an appended file it leaves unmoved keeps, and a file left out for that keeps its own position in turn', () => {
    const rows = [row(1, 5, 200_000, 'Row Five'), row(1, 6, 100_000, 'Row Six'), row(1, 7, 300_000, 'Row Seven')];
    // The first file's file-tag numbers (1, 5) do not fit its duration, so it is never numbered and keeps (1, 5); the second fits
    // only (1, 5) by duration and is left out.
    const two = appendDoc([400_000, 200_000], draft => { draft.tracks[0].discNumber = 1; draft.tracks[0].trackNumber = 5; },
        { [`tracks:${slot(0)}:discNumber`]: 'automatic', [`tracks:${slot(0)}:trackNumber`]: 'automatic' });
    assert.deepEqual(numberingOf(two, rows.slice(0, 2)), []);
    // The second file's lookup Track Number 6 does not constrain, so it pairs with (1, 5) and is left out; it then keeps (1, 6),
    // so the third file, which fits only (1, 6), is left out too, while the fourth still takes (1, 7).
    const chain = appendDoc([400_000, 200_000, 100_000, 300_000], draft => { Object.assign(draft.tracks[0], { discNumber: 1, trackNumber: 5 }); draft.tracks[1].trackNumber = 6; },
        { [`tracks:${slot(0)}:discNumber`]: 'automatic', [`tracks:${slot(0)}:trackNumber`]: 'automatic', [`tracks:${slot(1)}:trackNumber`]: 'automatic' });
    const lookup = { applied: { values: [{ path: `tracks.${slot(1)}.trackNumber`, value: 6, slotId: slot(1) }] } } as unknown as MetadataLookupRecord;
    assert.deepEqual(numberingOf(chain, rows, [], lookup), [{ slotId: slot(3), discNumber: 1, trackNumber: 7, title: 'Row Seven' }]);
    // A file the numbering moves frees its position: without the first file, the second leaves (1, 6) for (1, 5) and the third takes (1, 6).
    const moved = appendDoc([200_000, 100_000], draft => { draft.tracks[0].trackNumber = 6; }, { [`tracks:${slot(0)}:trackNumber`]: 'automatic' });
    const movedLookup = { applied: { values: [{ path: `tracks.${slot(0)}.trackNumber`, value: 6, slotId: slot(0) }] } } as unknown as MetadataLookupRecord;
    assert.deepEqual(numberingOf(moved, rows.slice(0, 2), [], movedLookup), [{ slotId: slot(0), discNumber: 1, trackNumber: 5, title: 'Row Five' },
        { slotId: slot(1), discNumber: 1, trackNumber: 6, title: 'Row Six' }]);
});
